"""Intent tests for M1-T16: risk.log_returns (RISK-01, TC-04)."""

from __future__ import annotations

import itertools
import math

import pytest

from mdata import Prices
from risk import Returns, log_returns


def _prices(data: dict) -> Prices:
    return Prices(
        dates=tuple(data["dates"]),
        tickers=tuple(data["tickers"]),
        closes={t: tuple(c) for t, c in data["closes"].items()},
    )


@pytest.mark.intent
def test_tc04_geometric_closes_give_closed_form_log_returns(golden):
    given, expected = golden("risk", "TC-04")
    returns = log_returns(_prices(given["prices"]))

    assert isinstance(returns, Returns)
    assert returns.base_date == expected["base_date"]
    assert list(returns.dates) == expected["dates"]
    assert list(returns.tickers) == expected["tickers"]
    assert set(returns.values) == set(expected["values"])
    for ticker, values in expected["values"].items():
        assert list(returns.values[ticker]) == pytest.approx(values, abs=expected["tol"])


@pytest.mark.intent
def test_returns_are_dated_t_and_equal_log_of_close_ratio(contract_sample):
    data = contract_sample("mdata.Prices")
    returns = log_returns(_prices(data))

    assert returns.base_date == data["dates"][0]
    assert list(returns.dates) == data["dates"][1:]
    assert list(returns.tickers) == data["tickers"]
    for ticker, closes in data["closes"].items():
        logs = [math.log(b / a) for a, b in itertools.pairwise(closes)]
        assert len(returns.values[ticker]) == len(logs)
        assert list(returns.values[ticker]) == pytest.approx(logs, abs=1e-12)


@pytest.mark.intent
def test_single_ticker_keeps_its_ticker(contract_sample):
    data = contract_sample("mdata.Prices")
    one = {
        "dates": data["dates"],
        "tickers": ["B"],
        "closes": {"B": data["closes"]["B"]},
    }
    returns = log_returns(_prices(one))

    assert returns.tickers == ("B",)
    assert set(returns.values) == {"B"}
    assert len(returns.values["B"]) == len(data["dates"]) - 1


@pytest.mark.intent
def test_fewer_than_two_dates_raises_value_error(contract_sample):
    data = contract_sample("mdata.Prices")
    single = {
        "dates": data["dates"][:1],
        "tickers": data["tickers"],
        "closes": {t: c[:1] for t, c in data["closes"].items()},
    }
    with pytest.raises(ValueError, match=r"(?i)two|2|date"):
        log_returns(_prices(single))

